<template>
  <section class="page"><div class="page-head"><div><div class="eyebrow">ACCOUNT / SETTINGS</div><h1>个人资料</h1><p>管理账户信息、登录密码和 API 偏好。</p></div></div><div class="profile-layout"><div class="panel profile-hero"><div class="profile-avatar">{{ initials }}</div><h2>{{ user.username }}</h2><p>{{ user.role === 'ADMIN' ? '管理员账户' : '标准用户' }}</p><div class="profile-meta"><span>账户 ID <b>#{{ user.id }}</b></span><span>注册于 <b>{{ format(user.created_at) }}</b></span></div></div><div class="panel"><div class="panel-head"><div><span class="eyebrow">ACCOUNT BINDING</span><h2>账户信息</h2></div></div><form @submit.prevent="saveProfile"><label>邮箱<input v-model.trim="email" type="email" placeholder="用于接收通知（可选）" /></label><button class="primary-btn" :disabled="saving">{{ saving ? '保存中…' : '保存资料' }}</button><p v-if="message" class="form-success">{{ message }}</p></form></div><div class="panel"><div class="panel-head"><div><span class="eyebrow">SECURITY</span><h2>修改密码</h2></div></div><form @submit.prevent="changePassword"><label>当前密码<input v-model="password.current_password" type="password" /></label><label>新密码<input v-model="password.new_password" type="password" minlength="6" /></label><label>确认新密码<input v-model="password.confirm" type="password" /></label><button class="secondary-btn" :disabled="savingPassword">{{ savingPassword ? '更新中…' : '更新密码' }}</button><p v-if="passwordMessage" class="form-success">{{ passwordMessage }}</p><p v-if="passwordError" class="form-error">{{ passwordError }}</p></form></div><div class="panel preference-panel"><div><span class="eyebrow">QUICK LINKS</span><h2>账户工具</h2></div><div class="profile-links"><router-link to="/keys" class="secondary-btn">管理 API 密钥 ↗</router-link><router-link to="/billing" class="secondary-btn">前往钱包 ↗</router-link><router-link to="/docs" class="secondary-btn">查看接入教程 ↗</router-link></div></div></div></section>
</template>
<script>
import { api } from '../api'
export default { props: { user: Object }, data: () => ({ email: '', saving: false, message: '', password: { current_password: '', new_password: '', confirm: '' }, savingPassword: false, passwordMessage: '', passwordError: '' }), computed: { initials () { return this.user?.username ? this.user.username.slice(0, 1).toUpperCase() : '' } }, created () { this.email = this.user?.email || '' }, methods: { async saveProfile () { this.saving = true; this.message = ''; try { const d = await api.updateProfile({ email: this.email }); if (!d.ok) throw new Error(d.message); this.message = '资料已保存'; this.$emit('refresh-user') } catch (e) { this.message = e.message } finally { this.saving = false } }, async changePassword () { this.passwordError = ''; this.passwordMessage = ''; if (this.password.new_password !== this.password.confirm) return (this.passwordError = '两次新密码不一致'); this.savingPassword = true; try { const d = await api.changePassword(this.password); if (!d.ok) throw new Error(d.message); this.passwordMessage = '密码已更新，请重新登录'; this.password = { current_password: '', new_password: '', confirm: '' } } catch (e) { this.passwordError = e.message } finally { this.savingPassword = false } }, format (value) { return value ? new Date(value).toLocaleDateString('zh-CN') : '-' } } }
</script>

